-- SIAKAD STT Diakonos - DEMO SEED v2 (data dummy, bukan data asli)
-- Generated untuk keperluan portfolio / testing, aman untuk dipublikasikan
-- Semua nama, NIM, NIDN, tanggal lahir, dan alamat di file ini FIKTIF
-- v2: 2 semester (1 selesai dengan nilai/KHS/presensi lengkap, 1 aktif dengan KRS berjalan)

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `audit_log`;
CREATE TABLE `audit_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int DEFAULT NULL,
  `action` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tableName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recordId` int DEFAULT NULL,
  `oldData` json DEFAULT NULL,
  `newData` json DEFAULT NULL,
  `ipAddress` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userAgent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `audit_log_userId_idx` (`userId`),
  KEY `audit_log_tableName_recordId_idx` (`tableName`,`recordId`),
  KEY `audit_log_createdAt_idx` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `program_studi`;
CREATE TABLE `program_studi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenjang` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'S1',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `program_studi_kode_key` (`kode`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ruangan`;
CREATE TABLE `ruangan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kapasitas` int DEFAULT '30',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ruangan_nama_key` (`nama`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `semester`;
CREATE TABLE `semester` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tahunAkademik` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `periode` enum('GANJIL','GENAP') COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggalMulai` datetime(3) NOT NULL,
  `tanggalSelesai` datetime(3) NOT NULL,
  `periodeKRSMulai` datetime(3) NOT NULL,
  `periodeKRSSelesai` datetime(3) NOT NULL,
  `periodePerbaikanKRSMulai` datetime(3) NOT NULL,
  `periodePerbaikanKRSSelesai` datetime(3) NOT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `semester_tahunAkademik_periode_key` (`tahunAkademik`,`periode`),
  KEY `semester_isActive_idx` (`isActive`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('ADMIN','DOSEN','MAHASISWA','KEUANGAN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MAHASISWA',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_username_key` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dosen`;
CREATE TABLE `dosen` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `nidn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nuptk` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `namaLengkap` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prodiId` int DEFAULT NULL,
  `tempatLahir` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggalLahir` datetime(3) DEFAULT NULL,
  `posisi` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jafung` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alumni` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lamaMengajar` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('AKTIF','NON_AKTIF') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AKTIF',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dosen_userId_key` (`userId`),
  UNIQUE KEY `dosen_nidn_key` (`nidn`),
  UNIQUE KEY `dosen_nuptk_key` (`nuptk`),
  KEY `dosen_nidn_idx` (`nidn`),
  KEY `dosen_prodiId_idx` (`prodiId`),
  CONSTRAINT `dosen_prodiId_fkey` FOREIGN KEY (`prodiId`) REFERENCES `program_studi` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `dosen_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mahasiswa`;
CREATE TABLE `mahasiswa` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `nim` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `namaLengkap` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tempatTanggalLahir` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenisKelamin` enum('L','P') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alamat` text COLLATE utf8mb4_unicode_ci,
  `prodiId` int NOT NULL,
  `angkatan` int NOT NULL,
  `status` enum('AKTIF','CUTI','NON_AKTIF','LULUS','DO') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AKTIF',
  `dosenWaliId` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `mahasiswa_userId_key` (`userId`),
  UNIQUE KEY `mahasiswa_nim_key` (`nim`),
  KEY `mahasiswa_nim_idx` (`nim`),
  KEY `mahasiswa_prodiId_idx` (`prodiId`),
  KEY `mahasiswa_angkatan_idx` (`angkatan`),
  KEY `mahasiswa_dosenWaliId_idx` (`dosenWaliId`),
  CONSTRAINT `mahasiswa_dosenWaliId_fkey` FOREIGN KEY (`dosenWaliId`) REFERENCES `dosen` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `mahasiswa_prodiId_fkey` FOREIGN KEY (`prodiId`) REFERENCES `program_studi` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `mahasiswa_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mata_kuliah`;
CREATE TABLE `mata_kuliah` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kodeMK` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `namaMK` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sks` int NOT NULL,
  `semesterIdeal` int NOT NULL,
  `isLintasProdi` tinyint(1) NOT NULL DEFAULT '0',
  `deskripsi` text COLLATE utf8mb4_unicode_ci,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `mata_kuliah_kodeMK_key` (`kodeMK`),
  KEY `mata_kuliah_kodeMK_idx` (`kodeMK`),
  KEY `mata_kuliah_semesterIdeal_idx` (`semesterIdeal`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `kelas_mata_kuliah`;
CREATE TABLE `kelas_mata_kuliah` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mkId` int NOT NULL,
  `semesterId` int NOT NULL,
  `dosenId` int NOT NULL,
  `hari` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jamMulai` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jamSelesai` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ruanganId` int NOT NULL,
  `kuotaMax` int NOT NULL DEFAULT '30',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `kelas_mata_kuliah_semesterId_idx` (`semesterId`),
  KEY `kelas_mata_kuliah_dosenId_idx` (`dosenId`),
  KEY `kelas_mata_kuliah_hari_jamMulai_idx` (`hari`,`jamMulai`),
  KEY `kelas_mata_kuliah_mkId_fkey` (`mkId`),
  KEY `kelas_mata_kuliah_ruanganId_fkey` (`ruanganId`),
  CONSTRAINT `kelas_mata_kuliah_dosenId_fkey` FOREIGN KEY (`dosenId`) REFERENCES `dosen` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `kelas_mata_kuliah_mkId_fkey` FOREIGN KEY (`mkId`) REFERENCES `mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `kelas_mata_kuliah_ruanganId_fkey` FOREIGN KEY (`ruanganId`) REFERENCES `ruangan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `kelas_mata_kuliah_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `kelas_mk_file`;
CREATE TABLE `kelas_mk_file` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kelasMKId` int NOT NULL,
  `tipeFile` enum('RPS','RPP','MATERI') COLLATE utf8mb4_unicode_ci NOT NULL,
  `namaFile` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fileUrl` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mingguKe` int DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `uploadedById` int NOT NULL,
  `uploadedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `kelas_mk_file_kelasMKId_idx` (`kelasMKId`),
  KEY `kelas_mk_file_tipeFile_idx` (`tipeFile`),
  KEY `kelas_mk_file_uploadedById_fkey` (`uploadedById`),
  CONSTRAINT `kelas_mk_file_kelasMKId_fkey` FOREIGN KEY (`kelasMKId`) REFERENCES `kelas_mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `kelas_mk_file_uploadedById_fkey` FOREIGN KEY (`uploadedById`) REFERENCES `dosen` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `khs`;
CREATE TABLE `khs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mahasiswaId` int NOT NULL,
  `semesterId` int NOT NULL,
  `ips` decimal(4,2) NOT NULL,
  `ipk` decimal(4,2) NOT NULL,
  `totalSKSSemester` int NOT NULL,
  `totalSKSKumulatif` int NOT NULL,
  `tanggalGenerate` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `khs_mahasiswaId_semesterId_key` (`mahasiswaId`,`semesterId`),
  KEY `khs_semesterId_idx` (`semesterId`),
  CONSTRAINT `khs_mahasiswaId_fkey` FOREIGN KEY (`mahasiswaId`) REFERENCES `mahasiswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `khs_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `krs`;
CREATE TABLE `krs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mahasiswaId` int NOT NULL,
  `semesterId` int NOT NULL,
  `paketKRSId` int DEFAULT NULL,
  `status` enum('DRAFT','SUBMITTED','APPROVED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `totalSKS` int NOT NULL DEFAULT '0',
  `isModified` tinyint(1) NOT NULL DEFAULT '0',
  `catatanAdmin` text COLLATE utf8mb4_unicode_ci,
  `tanggalSubmit` datetime(3) DEFAULT NULL,
  `tanggalApproval` datetime(3) DEFAULT NULL,
  `approvedById` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `krs_mahasiswaId_semesterId_key` (`mahasiswaId`,`semesterId`),
  KEY `krs_status_idx` (`status`),
  KEY `krs_semesterId_idx` (`semesterId`),
  KEY `krs_paketKRSId_fkey` (`paketKRSId`),
  KEY `krs_approvedById_fkey` (`approvedById`),
  CONSTRAINT `krs_approvedById_fkey` FOREIGN KEY (`approvedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `krs_mahasiswaId_fkey` FOREIGN KEY (`mahasiswaId`) REFERENCES `mahasiswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `krs_paketKRSId_fkey` FOREIGN KEY (`paketKRSId`) REFERENCES `paket_krs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `krs_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `krs_detail`;
CREATE TABLE `krs_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `krsId` int NOT NULL,
  `kelasMKId` int NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `krs_detail_krsId_kelasMKId_key` (`krsId`,`kelasMKId`),
  KEY `krs_detail_kelasMKId_fkey` (`kelasMKId`),
  CONSTRAINT `krs_detail_kelasMKId_fkey` FOREIGN KEY (`kelasMKId`) REFERENCES `kelas_mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `krs_detail_krsId_fkey` FOREIGN KEY (`krsId`) REFERENCES `krs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `nilai`;
CREATE TABLE `nilai` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mahasiswaId` int NOT NULL,
  `kelasMKId` int NOT NULL,
  `semesterId` int NOT NULL,
  `nilaiAngka` decimal(5,2) DEFAULT NULL,
  `nilaiHuruf` enum('A','AB','B','BC','C','CD','D','DE','E') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bobot` decimal(3,2) DEFAULT NULL,
  `isFinalized` tinyint(1) NOT NULL DEFAULT '0',
  `inputById` int NOT NULL,
  `tanggalInput` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nilai_mahasiswaId_kelasMKId_semesterId_key` (`mahasiswaId`,`kelasMKId`,`semesterId`),
  KEY `nilai_semesterId_idx` (`semesterId`),
  KEY `nilai_kelasMKId_idx` (`kelasMKId`),
  KEY `nilai_inputById_fkey` (`inputById`),
  CONSTRAINT `nilai_inputById_fkey` FOREIGN KEY (`inputById`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `nilai_kelasMKId_fkey` FOREIGN KEY (`kelasMKId`) REFERENCES `kelas_mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `nilai_mahasiswaId_fkey` FOREIGN KEY (`mahasiswaId`) REFERENCES `mahasiswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `nilai_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `paket_krs`;
CREATE TABLE `paket_krs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `namaPaket` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `angkatan` int NOT NULL,
  `prodiId` int NOT NULL,
  `semesterPaket` int NOT NULL,
  `semesterId` int NOT NULL,
  `totalSKS` int NOT NULL DEFAULT '0',
  `createdById` int NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `paket_krs_angkatan_prodiId_semesterPaket_idx` (`angkatan`,`prodiId`,`semesterPaket`),
  KEY `paket_krs_semesterId_fkey` (`semesterId`),
  KEY `paket_krs_prodiId_fkey` (`prodiId`),
  KEY `paket_krs_createdById_fkey` (`createdById`),
  CONSTRAINT `paket_krs_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `paket_krs_prodiId_fkey` FOREIGN KEY (`prodiId`) REFERENCES `program_studi` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `paket_krs_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `paket_krs_detail`;
CREATE TABLE `paket_krs_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `paketKRSId` int NOT NULL,
  `kelasMKId` int NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `paket_krs_detail_paketKRSId_kelasMKId_key` (`paketKRSId`,`kelasMKId`),
  KEY `paket_krs_detail_kelasMKId_fkey` (`kelasMKId`),
  CONSTRAINT `paket_krs_detail_kelasMKId_fkey` FOREIGN KEY (`kelasMKId`) REFERENCES `kelas_mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `paket_krs_detail_paketKRSId_fkey` FOREIGN KEY (`paketKRSId`) REFERENCES `paket_krs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pembayaran`;
CREATE TABLE `pembayaran` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mahasiswaId` int NOT NULL,
  `semesterId` int DEFAULT NULL,
  `jenisPembayaran` enum('KRS','TENGAH_SEMESTER','PPL','SKRIPSI','WISUDA','KOMITMEN_BULANAN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'KRS',
  `nominal` int NOT NULL,
  `buktiUrl` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PENDING','APPROVED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `bulanPembayaran` datetime(3) DEFAULT NULL,
  `uploadedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `verifiedAt` datetime(3) DEFAULT NULL,
  `verifiedById` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pembayaran_mahasiswaId_idx` (`mahasiswaId`),
  KEY `pembayaran_semesterId_idx` (`semesterId`),
  KEY `pembayaran_status_idx` (`status`),
  KEY `pembayaran_jenisPembayaran_idx` (`jenisPembayaran`),
  KEY `pembayaran_verifiedById_fkey` (`verifiedById`),
  CONSTRAINT `pembayaran_mahasiswaId_fkey` FOREIGN KEY (`mahasiswaId`) REFERENCES `mahasiswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pembayaran_semesterId_fkey` FOREIGN KEY (`semesterId`) REFERENCES `semester` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `pembayaran_verifiedById_fkey` FOREIGN KEY (`verifiedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `presensi`;
CREATE TABLE `presensi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kelasMKId` int NOT NULL,
  `tanggal` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `pertemuan` int NOT NULL,
  `materi` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `presensi_kelasMKId_pertemuan_key` (`kelasMKId`,`pertemuan`),
  KEY `presensi_kelasMKId_idx` (`kelasMKId`),
  KEY `presensi_tanggal_idx` (`tanggal`),
  CONSTRAINT `presensi_kelasMKId_fkey` FOREIGN KEY (`kelasMKId`) REFERENCES `kelas_mata_kuliah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `presensi_detail`;
CREATE TABLE `presensi_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `presensiId` int NOT NULL,
  `mahasiswaId` int NOT NULL,
  `status` enum('HADIR','TIDAK_HADIR','IZIN','SAKIT','ALPHA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ALPHA',
  `keterangan` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
